import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
} from "react";
import io from "socket.io-client";

const SocketContext = createContext(null);

export const useSocket = () => useContext(SocketContext);

export const SocketProvider = ({ children }) => {
  const [socket, setSocket] = useState(null);
  const [gameState, setGameState] = useState(null);

  useEffect(() => {
    const newSocket = io("http://localhost:3000");
    setSocket(newSocket);

    newSocket.on("gameCreated", (data) => setGameState(data));
    newSocket.on("playerJoined", (data) =>
      setGameState((prev) => ({ ...prev, ...data }))
    );
    newSocket.on("gameReady", (data) =>
      setGameState((prev) => ({ ...prev, ...data, status: "ready" }))
    );
    newSocket.on("playerLeft", (data) =>
      setGameState((prev) => ({ ...prev, ...data }))
    );
    newSocket.on("gameEnded", () => setGameState(null));
    newSocket.on("gameError", (error) => console.error("Game error:", error));
    newSocket.on("joinError", (error) => console.error("Join error:", error));

    return () => newSocket.close();
  }, []);

  const createGame = useCallback(
    (data) => {
      socket.emit("createGame", data);
    },
    [socket]
  );

  const joinGame = useCallback(
    ({ gameId, userId }) => {
      socket.emit("joinGame", { gameId, userId });
    },
    [socket]
  );

  const leaveGame = useCallback(
    ({ gameId, userId }) => {
      socket.emit("leaveGame", { gameId, userId });
    },
    [socket]
  );

  return (
    <SocketContext.Provider
      value={{ socket, gameState, createGame, joinGame, leaveGame }}
    >
      {children}
    </SocketContext.Provider>
  );
};
